"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[4941],{32935(e){e.exports=JSON.parse('{"tag":{"label":"clique","permalink":"/azeon/p-vs-np/tags/clique","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"real-world-impact/social-media-graph-algorithms","title":"Social Media Graph Algorithms","description":"A social network is a graph with billions of nodes. Finding the largest group where everyone knows everyone is the Clique problem from Post 15, NP-Hard and even hard to approximate. So platforms quietly ask easier questions instead.","permalink":"/azeon/p-vs-np/real-world-impact/social-media-graph-algorithms"},{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/independent-set","title":"The Independent Set Problem","description":"I have used Independent Set as a stepping stone twice without ever proving it is hard. Today I pay that debt, once the lazy way and once the honest way, straight from 3-SAT.","permalink":"/azeon/p-vs-np/np-completeness/independent-set"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"}],"unlisted":false}}')}}]);